// En este modo 'item' representa al usuario actual de la iteración
const currentUser = item.json;

// Leemos el informe RAG semanal (que es 1 solo resultado global)
const ragMetrics = $('Get Weekly Insights').first().json.get_weekly_insights;

// Devolvemos DIRECTAMENTE el objeto con los datos combinados (SIN corchetes de array [])
return {
  json: {
    phone: currentUser.phone,
    description: currentUser.description || "Productor musical generalista.",
    top_videos: ragMetrics.top_videos,
    top_hashtags: ragMetrics.top_hashtags,
    top_time_slots: ragMetrics.top_time_slots
  }
};

// Mapa región → zona horaria
const TZ_BY_REGION = {
  ES: 'Europe/Madrid',
  US: 'America/New_York',
  GB: 'Europe/London',
  MX: 'America/Mexico_City',
  AR: 'America/Argentina/Buenos_Aires',
  CO: 'America/Bogota',
  BR: 'America/Sao_Paulo',
  FR: 'Europe/Paris',
  DE: 'Europe/Berlin',
  IT: 'Europe/Rome',
  VN: 'Asia/Ho_Chi_Minh',
  ID: 'Asia/Jakarta',
  PH: 'Asia/Manila',
  JP: 'Asia/Tokyo',
  KR: 'Asia/Seoul',
};

const scrapedAt = DateTime.utc();

return $input.all().map(item => {
  const v = item.json;

  const stats  = v.statistics || {};
  const author = v.author || {};
  const music  = v.music || {};

  // --- Hashtags (Devolvemos un Array de JS nativo) ---
  let hashtags = (v.text_extra || [])
    .filter(t => t.type === 1 && t.hashtag_name)
    .map(t => t.hashtag_name.toLowerCase());

  if (hashtags.length === 0) {
    hashtags = (v.cha_list || [])
      .map(c => (c.cha_name || '').toLowerCase())
      .filter(Boolean);
  }
  hashtags = [...new Set(hashtags)];

  // --- Fechas ---
  const createdAtUTC =
    DateTime.fromSeconds(Number(v.create_time || 0), { zone: 'utc' });
  const tz = TZ_BY_REGION[v.region] || 'utc';
  const createdAtLocal = createdAtUTC.setZone(tz);

  // --- Growth score ---
  const playCount = Number(stats.play_count || 0);
  const hoursSince =
    Math.max(scrapedAt.diff(createdAtUTC, 'hours').hours, 1);
  const growthScore = Number((playCount / hoursSince).toFixed(2));

  const username = author.unique_id || null;

  return { json: {
    id: String(v.aweme_id),
    description: v.desc || null,
    // CLAVE: Se pasa el Array de JavaScript directo. NO usar JSON.stringify aquí.
    hashtags: JSON.stringify(hashtags), 
    music_name: music.title || null,
    music_author: music.author || music.owner_nickname || null,
    music_original: Boolean(
      music.is_original_sound ?? music.is_original ?? false
    ),
    video_url: username
      ? `https://www.tiktok.com/@${username}/video/${v.aweme_id}`
      : (v.share_url || null),
    play_count: playCount,
    like_count: Number(stats.digg_count || 0),
    share_count: Number(stats.share_count || 0),
    comment_count: Number(stats.comment_count || 0),
    duration: v.video?.duration
      ? Math.round(v.video.duration / 1000)
      : (music.duration ?? null),
    created_at: createdAtUTC.toISO(),
    growth_score: growthScore,
    scraped_at: scrapedAt.toISO(),
    region: v.region || null,
    profile_url: username
      ? `https://www.tiktok.com/@${username}`
      : null,
    author_id: String(author.uid || v.author_user_id || ''),
    author_username: username,
    follower_count: Number(author.follower_count || 0),
    created_at_local: createdAtLocal.toISO(),
    is_ad: Boolean(
      v.is_ads ||
      v.commerce_info?.auction_ad_invited ||
      v.with_promotional_music),
  }};
});

// Capturamos los datos del item actual
const inputItem = $input.first().json;

// 1. Comprobamos si el nodo anterior ha registrado un error de n8n/Gemini
const hasError = inputItem.error !== undefined || $node["AI Agent"]?.error !== undefined;

let userReply = "";
let rawErrorDetails = "";

if (hasError) {
  // Extraemos el mensaje de error o la pila técnica si existen
  const errObject = inputItem.error || $node["AI Agent"]?.error;
  rawErrorDetails = typeof errObject === 'object' ? JSON.stringify(errObject) : String(errObject);

  // 2. Interpretación amigable según el tipo de error
  if (rawErrorDetails.includes("503") || rawErrorDetails.includes("high demand")) {
    userReply = "⚠️ *Servidor ocupado:* El modelo de IA de Google está experimentando una alta demanda temporal. Por favor, inténtalo de nuevo en unos segundos.";
  } else if (rawErrorDetails.includes("429") || rawErrorDetails.includes("Quota")) {
    userReply = "⏳ *Límite alcanzado:* Se ha superado la cuota temporal de consultas. Espera un par de minutos antes de enviar otro mensaje.";
  } else if (rawErrorDetails.includes("timeout") || rawErrorDetails.includes("ETIMEDOUT")) {
    userReply = "⏱️ *Tiempo de espera agotado:* La respuesta ha tardado más de lo esperado en procesarse. Por favor, vuelve a intentarlo.";
  } else {
    // Respuesta genérica para otros errores
    userReply = "❌ *Lo sentimos:* Ha ocurrido un inconveniente procesando tu solicitud en este momento. Por favor, vuelve a intentarlo más tarde.";
  }
} else {
  // 3. Si todo funcionó bien, obtenemos la respuesta normal del Agente
  userReply = inputItem.output || inputItem.text || inputItem.chat_output || "Respuesta procesada correctamente.";
}

const sessionId = $("Format Input").first()?.json?.phone,

return [{
  json: {
    ...$json,
    is_error: hasError,
    // Este campo es el que debes enviar en el nodo final de respuesta de WhatsApp
    whatsapp_message: userReply,
    from: sessionId,
    // Detalle técnico mantenido por si quieres registrarlo en base de datos o logs
    error_details: hasError ? rawErrorDetails : null
  }
}];

// Si venimos de la rama de error o la normal, $json ya tiene el formato correcto
const input = $json;

return [{
  json: {
    ...input,
    from: input.session_id,
    raw_ideas: input.raw_content || null,
    whatsapp_message: input.message,
    is_error: input.is_error || false,
    error_details: input.error_details || null,
  }
}];

let responseJson;
const rawOutput = $json.output || "";

try {
  responseJson = typeof rawOutput === 'object' ? rawOutput : JSON.parse(rawOutput.replace(/```json|```/g, '').trim());
} catch (e) {
  throw new Error("No se pudo parsear el JSON del agente: " + e.message);
}

const ideas = responseJson.weekly_ideas || [];
const slots = responseJson.best_time_slots || [];

// 1. Pre-construimos el bloque de horarios para conocer su longitud exacta de antemano
let slotsMessage = "";
if (slots.length > 0) {
  slotsMessage += `⏰ *MEJORES HORARIOS DE PUBLICACIÓN:*\n`;
  slots.forEach(slot => {
    slotsMessage += `• ${slot}\n`;
  });
}

// 2. Encabezado principal
let message = `🚀 *TUS IDEAS DE CONTENIDO DE LA SEMANA* 🎛️\n\n`;

const MAX_CHARACTERS = 3900; // Margen de seguridad sobre los 4096 de WhatsApp

// 3. Iteramos las ideas y solo añadimos la siguiente si no supera el límite total junto a los horarios
for (let index = 0; index < ideas.length; index++) {
  const idea = ideas[index];

  let ideaBlock = `*${index + 1}. ${idea.title.toUpperCase()}*\n`;
  ideaBlock += `🪝 *Gancho (3s):* ${idea.hook}\n`;
  ideaBlock += `🛠️ *Desarrollo:* ${idea.development}\n`;
  ideaBlock += `📝 *Copy:* ${idea.copy}\n`;
  if (idea.hashtags && idea.hashtags.length > 0) {
    ideaBlock += `🏷️ *Hashtags:* ${idea.hashtags.join(' ')}\n`;
  }
  ideaBlock += `\n\n`;

  // Comprobamos si añadir esta idea sobrepasaría el límite reservando espacio para los horarios
  const projectedLength = message.length + ideaBlock.length + slotsMessage.length;

  if (projectedLength > MAX_CHARACTERS) {
    // Si la idea no cabe completa, salimos del bucle sin alterarla ni cortarla a la mitad
    break;
  }

  message += ideaBlock;
}

// 4. Añadimos el bloque de horarios al final
if (slotsMessage) {
  message += slotsMessage;
}

const sessionId = $("Format Input").first()?.json?.phone;

return [{
  json: {
    from: sessionId,
    whatsapp_message: message.trim(),
    raw_ideas: responseJson
  }
}];
